import { test } from "@e2e/fixtures";
import * as flows from "@e2e/flows";
import * as ui from "@e2e/ui-actions";

test.describe("Accessibility", () => {
  test.use({
    inspectorOptions: {
      inspectMode: true,
    },
  });

  test("Event details close button is activatable via keyboard Enter", async ({
    inspectorPage,
  }) => {
    await flows.chat.openConversationEventDetailsAndAssert(inspectorPage, {
      eventName: "Flow welcome started",
      panelTitle: "Flow event",
    });

    await test.step("Close event details via keyboard Enter", async () => {
      await ui.eventDetails.actions(inspectorPage).focusCloseButton();
      await ui.eventDetails.actions(inspectorPage).pressEnter();
      await ui.eventDetails.assertions(inspectorPage).panelIsHidden();
    });
  });
});
